use super::*;
use serde_json::{Value,json};
use std::panic::{catch_unwind,AssertUnwindSafe};
use io_poi_compact::cn::wps::encrypt::{CryptTool::CryptTool,Base64::Base64};
fn call<T:serde::Serialize>(f:impl FnOnce()->T)->Value{match catch_unwind(AssertUnwindSafe(f)){Ok(v)=>json!({"result":"ok","value":v}),Err(e)=>{let s=e.downcast_ref::<String>().map(String::as_str).or_else(||e.downcast_ref::<&str>().copied()).unwrap_or("");let name=["NullPointerException","IllegalArgumentException","ArrayIndexOutOfBoundsException","RuntimeException"].into_iter().find(|n|s.starts_with(n)).unwrap_or(s);json!({"result":name})}}}
fn hex(b:&[u8])->String{b.iter().map(|v|format!("{v:02x}")).collect()}
fn verifier(m:&ModifyVerifier)->Value{json!({"hash":m.getHashData(),"salt":m.getSaltData(),"spin":m.getSpinCount(),"algorithm":m.getAlogrithmSid()})}
fn check(p:&Value)->Value{let m=if p["nullVerifier"]==true{None}else{Some(ModifyVerifier::new_with_algorithm__nullable(p["hash"].as_str(),p["salt"].as_str(),p["spin"].as_i64().unwrap()as i32,p["algorithm"].as_i64().unwrap()as i32))};call(||CryptTool::checkModifyPassword__nullable(m.as_ref(),p["password"].as_str()))}
fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}
#[test]fn original_android_modification_password_crypto_and_base64(){let p=std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("rewrite-review/milestones/m4-edit-save/evidence/modify-password-r0b61");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let chars=(0..65536).filter_map(char::from_u32).map(|ch|call(||hex(&Base64::base64ToByteArray_simple(&format!("AAA{ch}"))))).collect::<Vec<_>>();let base64=input["base64"].as_array().unwrap().iter().map(|s|call(||hex(&Base64::base64ToByteArray_simple(s.as_str().unwrap())))).collect::<Vec<_>>();let mut rows=vec![];for s in input["passwords"].as_array().unwrap(){let password=s.as_str().unwrap();let m=CryptTool::createModifyVerifierSHA512(password);let m1=CryptTool::createModifyVerifier(password);rows.push(json!({"sha512":verifier(&m),"sha1":verifier(&m1),"correct":CryptTool::checkModifyPassword(&m,password),"wrong":CryptTool::checkModifyPassword(&m,&format!("{password}x")),"sha1Correct":CryptTool::checkModifyPassword(&m1,password),"null":call(||CryptTool::checkModifyPassword__nullable(Some(&m),None))}));}let actual=json!({"base64Bmp":chars,"base64":base64,"checks":input["checks"].as_array().unwrap().iter().map(check).collect::<Vec<_>>(),"passwords":rows,"nullCreate":call(||{CryptTool::createModifyVerifierSHA512__nullable(None);})});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();compare(&actual,&java,"root");}
